45|     padding: 8px 16px;
46|     border-radius: 12px;
47|     box-shadow: 0 3px 6px rgba(0,0,0,0.25);
48|     pointer-events: none;
49|   }
50|   #clearBtn {
51|     pointer-events: auto;
52|     background: #e07a5f;
53|     color: #f4ecd8;
54|     border: none;
55|     font-weight: 700;
56|     font-size: 16px;
57|     padding: 10px 20px;
58|     min-height: 44px;
59|     border-radius: 14px;
60|     box-shadow: 0 3px 6px rgba(0,0,0,0.3);
61|     cursor: pointer;
62|   }
63|   #clearBtn:active {
64|     transform: translateY(1px);
65|   }
66| </style>
67| </head>
68| <body>
69| <div id="wrap">
70|   <canvas id="game"></canvas>
71|   <div id="bar">
72|     <div id="counter">Stickers: 0</div>
73|     <button id="clearBtn">Clear</button>
74|   </div>
75| </div>
76| <script>
77| const CARTRIDGE = {
78|   send(type, payload = {}) {
79|     window.parent.postMessage(
80|       { source: "cartridge", v: 1, type, payload },
81|       "*",
82|     );
83|   },
84| };
85| </script>
86| <script>
87| (function() {
88|   const canvas = document.getElementById("game");
89|   const ctx = canvas.getContext("2d");
90|   const clearBtn = document.getElementById("clearBtn");
91|   const counterEl = document.getElementById("counter");
92| 
93|   let dpr = Math.max(1, window.devicePixelRatio || 1);
94|   let W = 0, H = 0;
95| 
96|   function resize() {
97|     W = window.innerWidth;
98|     H = window.innerHeight;
99|     dpr = Math.max(1, window.devicePixelRatio || 1);
100|     canvas.width = Math.round(W * dpr);
101|     canvas.height = Math.round(H * dpr);
102|     canvas.style.width = W + "px";
103|     canvas.style.height = H + "px";
104|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
105|     draw();
106|   }
107|   window.addEventListener("resize", resize);
108| 
109|   // ---- state ----
110|   const pieces = [];
111|   let tally = 0;
112|   let paused = false;
113|   let running = false;
114|   let hintPulse = 0;
115| 
116|   const kinds = ["leaf", "shell", "star"];
117|   let nextKindIndex = 0;
118| 
119|   // simple seeded jitter generator per piece so shapes stay stable
120|   function mulberry32(seed) {
121|     return function() {
122|       seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
123|       let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
124|       t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
125|       return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
126|     };
127|   }
128| 
129|   function jitterPoints(points, seed, amount) {
130|     const rnd = mulberry32(seed);
131|     return points.map(p => [
132|       p[0] + (rnd() - 0.5) * amount * 2,
133|       p[1] + (rnd() - 0.5) * amount * 2
134|     ]);
135|   }
136| 
137|   function place(x, y) {
138|     const kind = kinds[nextKindIndex % kinds.length];
139|     nextKindIndex++;
140|     const seed = Math.floor(Math.random() * 1e9);
141|     const rot = (Math.random() - 0.5) * 0.6;
142|     const scale = 0.85 + Math.random() * 0.35;
143|     pieces.push({
144|       x, y, kind, seed, rot, scale,
145|       born: performance.now(),
146|       wobble: 1
147|     });
148|     tally += 1;
149|     counterEl.textContent = "Stickers: " + tally;
150|     CARTRIDGE.send("score", { value: tally });
151|   }
152| 
153|   // One clear-the-table function: empties pieces, zeroes tally,
154|   // resets to the pre-start screen. Called by the visible Clear
155|   // button AND by the host "reset" command.
156|   function clearTable() {
157|     pieces.length = 0;
158|     tally = 0;
159|     counterEl.textContent = "Stickers: 0";
160|     CARTRIDGE.send("score", { value: 0 });
161|     running = false;
162|     draw();
163|   }
164| 
165|   clearBtn.addEventListener("click", clearTable);
166| 
167|   // ---- drawing helpers (paper-cut style) ----
168|   const COLORS = {
169|     bg: "#f4ecd8",
170|     layer: "#e07a5f",
171|     accent: "#3d405b",
172|     highlight: "#81b29a"
173|   };
174| 
175|   function roundedPolygon(ctx, pts, radius) {
176|     // simple polygon path (no rounding complexity needed at this scale)
177|     ctx.beginPath();
178|     ctx.moveTo(pts[0][0], pts[0][1]);
179|     for (let i = 1; i < pts.length; i++) {
180|       ctx.lineTo(pts[i][0], pts[i][1]);
181|     }
182|     ctx.closePath();
183|   }
184| 
185|   function drawLeaf(ctx, seed, scale) {
186|     const base = [
187|       [0, -26], [12, -10], [14, 8], [0, 26], [-14, 8], [-12, -10]
188|     ].map(p => [p[0]*scale, p[1]*scale]);
189|     const pts = jitterPoints(base, seed, 1.5);
190|     ctx.fillStyle = COLORS.highlight;
191|     ctx.shadowColor = "rgba(61,64,91,0.35)";
192|     ctx.shadowBlur = 6;
193|     ctx.shadowOffsetY = 3;
194|     roundedPolygon(ctx, pts, 4);
195|     ctx.fill();
196|     ctx.shadowColor = "transparent";
197|     ctx.strokeStyle = COLORS.accent;
198|     ctx.lineWidth = 1.5;
199|     ctx.beginPath();
200|     ctx.moveTo(0, -22*scale);
201|     ctx.lineTo(0, 22*scale);
202|     ctx.stroke();
203|   }
204| 
205|   function drawShell(ctx, seed, scale) {
206|     const pts = [];
207|     const n = 10;
208|     for (let i = 0; i <= n; i++) {
209|       const a = Math.PI * (i / n) - Math.PI / 2;
210|       const r = 22 * scale;
211|       pts.push([Math.cos(a) * r, Math.sin(a) * r - 4*scale]);
212|     }
213|     pts.push([0, 20*scale]);
214|     const jp = jitterPoints(pts, seed, 1.5);
215|     ctx.fillStyle = COLORS.layer;
216|     ctx.shadowColor = "rgba(61,64,91,0.35)";
217|     ctx.shadowBlur = 6;
218|     ctx.shadowOffsetY = 3;
219|     roundedPolygon(ctx, jp, 4);
220|     ctx.fill();
221|     ctx.shadowColor = "transparent";
222|     ctx.strokeStyle = COLORS.accent;
223|     ctx.lineWidth = 1.2;
224|     for (let i = 1; i < 5; i++) {
225|       const a = Math.PI * (i / 5) - Math.PI / 2;
226|       ctx.beginPath();
227|       ctx.moveTo(0, 18*scale);
228|       ctx.lineTo(Math.cos(a) * 20*scale, Math.sin(a) * 20*scale - 4*scale);
229|       ctx.stroke();
230|     }
231|   }
232| 
233|   function drawStar(ctx, seed, scale) {
234|     const pts = [];
235|     const spikes = 5;
236|     const outer = 22 * scale;
237|     const inner = 9 * scale;
238|     for (let i = 0; i < spikes * 2; i++) {
239|       const r = i % 2 === 0 ? outer : inner;
240|       const a = (Math.PI / spikes) * i - Math.PI / 2;
241|       pts.push([Math.cos(a) * r, Math.sin(a) * r]);
242|     }
243|     const jp = jitterPoints(pts, seed, 1.2);
244|     ctx.fillStyle = COLORS.accent;
245|     ctx.shadowColor = "rgba(61,64,91,0.35)";
246|     ctx.shadowBlur = 6;
247|     ctx.shadowOffsetY = 3;
248|     roundedPolygon(ctx, jp, 3);
249|     ctx.fill();
250|     ctx.shadowColor = "transparent";
251|   }
252| 
253|   function drawPiece(p, now) {
254|     const age = now - p.born;
255|     const wobbleT = Math.min(age / 500, 1);
256|     const wobble = Math.sin(wobbleT * Math.PI * 3) * (1 - wobbleT) * 0.15;
257|     ctx.save();
258|     ctx.translate(p.x, p.y);
259|     ctx.rotate(p.rot + wobble);
260|     const s = p.scale * (0.7 + 0.3 * Math.min(age / 250, 1));
261|     ctx.scale(s, s);
262|     if (p.kind === "leaf") drawLeaf(ctx, p.seed, 1);
263|     else if (p.kind === "shell") drawShell(ctx, p.seed, 1);
264|     else drawStar(ctx, p.seed, 1);
265|     ctx.restore();
266|   }
267| 
268|   function drawBackground() {
269|     ctx.fillStyle = COLORS.bg;
270|     ctx.fillRect(0, 0, W, H);
271|     // subtle table plate - layered rounded rect
272|     const margin = 14;
273|     const w = W - margin * 2;
274|     const h = H - margin * 2;
275|     ctx.save();
276|     ctx.shadowColor = "rgba(61,64,91,0.25)";
277|     ctx.shadowBlur = 8;
278|     ctx.shadowOffsetY = 4;
279|     ctx.fillStyle = "#efe3c8";
280|     roundRect(ctx, margin, margin, w, h, 24);
281|     ctx.fill();
282|     ctx.restore();
283|   }
284| 
285|   function roundRect(ctx, x, y, w, h, r) {
286|     ctx.beginPath();
287|     ctx.moveTo(x + r, y);
288|     ctx.arcTo(x + w, y, x + w, y + h, r);
289|     ctx.arcTo(x + w, y + h, x, y + h, r);
290|     ctx.arcTo(x, y + h, x, y, r);
291|     ctx.arcTo(x, y, x + w, y, r);
292|     ctx.closePath();
293|   }
294| 
295|   function drawHint() {
296|     if (running) return;
297|     hintPulse += 0.05;
298|     const alpha = 0.55 + Math.sin(hintPulse) * 0.35;
299|     ctx.save();
300|     ctx.globalAlpha = Math.max(0.15, alpha);
301|     ctx.fillStyle = COLORS.accent;
302|     ctx.font = "bold 26px sans-serif";
303|     ctx.textAlign = "center";
304|     ctx.textBaseline = "middle";
305|     ctx.fillText("Tap to begin", W / 2, H / 2);
306|     ctx.restore();
307|   }
308| 
309|   function draw() {
310|     drawBackground();
311|     const now = performance.now();
312|     for (const p of pieces) drawPiece(p, now);
313|     drawHint();
314|   }
315| 
316|   function frame() {
317|     if (!paused) {
318|       // no physics settling needed beyond wobble animation via time
319|     }
320|     draw();
321|     requestAnimationFrame(frame);
322|   }
323| 
324|   // ---- input ----
325|   canvas.style.touchAction = "none";
326|   canvas.addEventListener("pointerdown", (event) => {
327|     event.preventDefault();
328|     if (paused) return;
329|     const rect = canvas.getBoundingClientRect();
330|     const x = event.clientX - rect.left;
331|     const y = event.clientY - rect.top;
332|     if (!running) {
333|       running = true;
334|       CARTRIDGE.send("start");
335|       place(x, y);
336|       return;
337|     }
338|     place(x, y);
339|   });
340| 
341|   // ---- host messages ----
342|   window.addEventListener("message", (event) => {
343|     const data = event.data;
344|     if (!data || data.source !== "cartridge-host") return;
345|     if (data.type === "pause") paused = true;
346|     if (data.type === "resume") paused = false;
347|     if (data.type === "reset") clearTable();
348|   });
349| 
350|   // ---- boot ----
351|   resize();
352|   CARTRIDGE.send("boot", { title: "Sticker Table", gameType: "toy-box", lang: "en" });
353|   requestAnimationFrame(frame);
354| })();
355| </script>
356| </body>
357| </html>
358|

